def can_chain(dominoes):
    """Return a closed chain of dominoes, or None if no such chain exists.

    A chain is a list of (left, right) tuples where each domino's right
    half matches the next domino's left half, and the first domino's
    left half matches the last domino's right half.
    """
    if not dominoes:
        return []

    def backtrack(remaining, chain, start):
        if not remaining:
            return chain if chain[-1][1] == start else None
        last = chain[-1][1]
        for i, domino in enumerate(remaining):
            for orientation in ((domino[0], domino[1]), (domino[1], domino[0])):
                if orientation[0] != last:
                    continue
                rest = remaining[:i] + remaining[i + 1:]
                result = backtrack(rest, chain + [orientation], start)
                if result is not None:
                    return result
        return None

    for i, domino in enumerate(dominoes):
        for orientation in ((domino[0], domino[1]), (domino[1], domino[0])):
            rest = dominoes[:i] + dominoes[i + 1:]
            result = backtrack(rest, [orientation], orientation[0])
            if result is not None:
                return result
    return None

